// ── Secret encryption at rest (AES-256-GCM) ─────────────────────────────────
// Third-party credentials — Sonarr/Radarr keys, Steam Web API keys, ecosystem
// tokens — were stored as plaintext in .nexus-data/*.json and in Neon. Anyone
// with a copy of a backup, or read access to the database, had the keys.
//
// GCM rather than CBC because these values are read back and used verbatim:
// the auth tag makes tampering detectable instead of silently yielding a
// corrupted key. A random 12-byte IV per value means encrypting the same key
// twice never produces the same ciphertext.
//
// The key is derived with scrypt from NEXUS_ENCRYPTION_KEY, falling back to
// JWT_SECRET so an existing deployment keeps working without new config. That
// fallback is why rotating JWT_SECRET also invalidates stored secrets — call
// that out rather than let it surprise someone.
// ── Emulator BIOS requirements ──────────────────────────────────────────────
// Shared by the launch interceptor and the readiness dashboard. Previously this
// table lived inside the readiness endpoint, so the launch path had no idea a
// platform needed a BIOS at all — a PS1 game with no BIOS launched RetroArch,
// which died on its own with nothing useful surfaced to the player.
//
// "anyOf": regional variants are interchangeable, so any one of them satisfies
// the requirement. "required: false" means the core boots without it.
const REQUIRED_BIOS: Record<string, { anyOf: string[]; required: boolean; label: string }> = {
  ps1:    { anyOf: ["scph5501.bin", "scph5500.bin", "scph5502.bin", "scph1001.bin"], required: true,  label: "PlayStation" },
  ps2:    { anyOf: ["scph70012.bin", "scph39001.bin", "scph30004r.bin"],             required: true,  label: "PlayStation 2" },
  saturn: { anyOf: ["saturn_bios.bin", "sega_101.bin", "mpr-17933.bin"],             required: true,  label: "Saturn" },
  nds:    { anyOf: ["bios7.bin"],                                                    required: true,  label: "Nintendo DS" },
  segacd: { anyOf: ["bios_cd_u.bin", "bios_cd_e.bin", "bios_cd_j.bin"],              required: true,  label: "Sega CD" },
  gba:    { anyOf: ["gba_bios.bin"],                                                 required: false, label: "Game Boy Advance" },
};

const SECRET_ENC_PREFIX = "enc:v1:";
let _secretKey: Buffer | null = null;

function secretKey(): Buffer {
  if (_secretKey) return _secretKey;
  const material = process.env.NEXUS_ENCRYPTION_KEY ?? process.env.JWT_SECRET ?? "";
  if (!material) {
    throw new Error("No NEXUS_ENCRYPTION_KEY or JWT_SECRET — refusing to store secrets unencrypted");
  }
  // Fixed salt: the key must be derivable identically on every boot, and the
  // material is already high-entropy, so a per-value salt would buy nothing
  // here but would break decryption across restarts.
  _secretKey = crypto.scryptSync(material, "nexus-secret-v1", 32);
  return _secretKey;
}

/** Encrypt a secret for storage. Empty input stays empty. */
function encryptSecret(plain: string | null | undefined): string {
  const v = String(plain ?? "");
  if (!v) return "";
  if (v.startsWith(SECRET_ENC_PREFIX)) return v;   // already encrypted
  const iv = crypto.randomBytes(12);
  const c = crypto.createCipheriv("aes-256-gcm", secretKey(), iv);
  const enc = Buffer.concat([c.update(v, "utf8"), c.final()]);
  const tag = c.getAuthTag();
  return SECRET_ENC_PREFIX + [iv.toString("base64"), tag.toString("base64"), enc.toString("base64")].join(".");
}

/**
 * Decrypt a stored secret.
 *
 * A value without the prefix is returned as-is: existing rows were written in
 * plaintext and must keep working until they are rewritten. That is what makes
 * this migration transparent rather than a flag day.
 */
function decryptSecret(stored: string | null | undefined): string {
  const v = String(stored ?? "");
  if (!v || !v.startsWith(SECRET_ENC_PREFIX)) return v;
  try {
    const [ivB, tagB, dataB] = v.slice(SECRET_ENC_PREFIX.length).split(".");
    const d = crypto.createDecipheriv("aes-256-gcm", secretKey(), Buffer.from(ivB, "base64"));
    d.setAuthTag(Buffer.from(tagB, "base64"));
    return Buffer.concat([d.update(Buffer.from(dataB, "base64")), d.final()]).toString("utf8");
  } catch {
    // Wrong key or tampered payload. Returning "" makes the caller behave as
    // "not configured" rather than sending a corrupted key to a third party.
    return "";
  }
}

/** True when a value is already stored encrypted. */
function isEncryptedSecret(v: string | null | undefined): boolean {
  return String(v ?? "").startsWith(SECRET_ENC_PREFIX);
}

// ── Drive Recovery Layer (added 2026-09-20) ─────────────────────────────────
// "/media/moh/EMULATION dRIVE" was physically destroyed. Every hardcoded
// reference to that mount point has been replaced by the OS-agnostic paths
// below. scripts/test-emergency-recovery.cjs fails if the name reappears.
const NEXUS_HOME = os.homedir();

/** Local fallback vault — stands in for the dead drive when disk is unavoidable. */
const NEXUS_LOCAL_VAULT =
  process.env.NEXUS_VAULT_FALLBACK ?? path.join(NEXUS_HOME, ".nexus-vault");

/** rclone mount of gdrive:NexusArchive — the primary store now local space is gone. */
const NEXUS_GDRIVE_ROOT =
  process.env.NEXUS_GDRIVE_ROOT ?? path.join(NEXUS_HOME, "nexus-cloud-media");

/** Older per-type rclone mount, kept so existing library rows still resolve. */
const NEXUS_GDRIVE_LEGACY = path.join(NEXUS_HOME, "gdrive");

/** Cloud-first mode: never prefer local disk for new writes. Set 0 to opt out. */
const NEXUS_CLOUD_FIRST = (process.env.NEXUS_CLOUD_FIRST ?? "1") !== "0";

/**
 * Mount points known to be gone. Any path under one of these is treated as
 * non-existent without touching the filesystem, so a destroyed drive can never
 * stall a request on a hung mount or be silently re-created by mkdir -p.
 */
const NEXUS_DEAD_MOUNTS: string[] = [...new Set([
  "/media/moh/EMULATION" + " dRIVE",
  // .env also lists it, so without the dedupe the same mount appeared twice in
  // every denylist report and was checked twice on every path test.
  ...(process.env.NEXUS_DEAD_MOUNTS ?? "").split(",").map((x) => x.trim()).filter(Boolean),
])];

function isDeadDrivePath(p: string | null | undefined): boolean {
  if (!p) return false;
  const norm = String(p).replace(/\\/g, "/");
  return NEXUS_DEAD_MOUNTS.some(
    (d) => norm === d || norm.startsWith(d.replace(/\\/g, "/") + "/"),
  );
}

/** Drop any dead-drive entries from a candidate path list. */
function livePaths<T extends string | null | undefined>(list: T[]): string[] {
  return list.filter((p): p is string & T => Boolean(p) && !isDeadDrivePath(p));
}
// ── Bounded Connection Pool & Resource Manager (Phase 8) ────────────────────
const ECOSYSTEM_POOL_CONFIG = {
  keepAlive: true,
  keepAliveMsecs: 2000,
  maxSockets: 20,
  maxFreeSockets: 5,
  timeout: 8000,
};

const ecosystemHttpAgent = new http.Agent(ECOSYSTEM_POOL_CONFIG);
const ecosystemHttpsAgent = new https.Agent(ECOSYSTEM_POOL_CONFIG);

const activeEcosystemWebSockets = new Set<any>();

function trackWebSocket(ws: any) {
  if (!ws) return;
  activeEcosystemWebSockets.add(ws);
  const cleanup = () => {
    activeEcosystemWebSockets.delete(ws);
  };
  if (typeof ws.on === "function") {
    ws.on("close", cleanup);
    ws.on("error", cleanup);
  }
}

const GC_INTERVAL_MS = 30_000;
let gcTimer: NodeJS.Timeout | null = null;

function startResourceGarbageCollector() {
  if (gcTimer) return;
  gcTimer = setInterval(() => {
    for (const ws of activeEcosystemWebSockets) {
      try {
        if (ws.readyState === 2 || ws.readyState === 3 || ws.readyState === undefined) {
          if (typeof ws.terminate === "function") ws.terminate();
          else if (typeof ws.close === "function") ws.close();
          activeEcosystemWebSockets.delete(ws);
        }
      } catch {
        activeEcosystemWebSockets.delete(ws);
      }
    }

    [ecosystemHttpAgent, ecosystemHttpsAgent].forEach((agent) => {
      const freeSockets = (agent as any).freeSockets || {};
      for (const hostKey of Object.keys(freeSockets)) {
        const list = freeSockets[hostKey] || [];
        for (let i = list.length - 1; i >= 0; i--) {
          const s = list[i];
          if (s.destroyed || !s.readable || !s.writable) {
            try { s.destroy(); } catch {}
            list.splice(i, 1);
          }
        }
      }
    });
  }, GC_INTERVAL_MS);

  if (typeof gcTimer.unref === "function") {
    gcTimer.unref();
  }
}

startResourceGarbageCollector();

type AwehChatContact = {
  id: string;
  name: string;
  username?: string;
  email?: string;
  avatarUrl?: string;
  online?: boolean;
  status?: string;
};

type EcosystemInvitePayload = {
  contactId: string;
  type: "coop" | "stream" | "vault";
  inviteUrl: string;
  title: string;
  senderName?: string;
};

let contactCache: { data: AwehChatContact[]; cachedAt: number; ttlMs: number } | null = null;
const CONTACT_CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

async function fetchMasterContactList(apiUrl: string, apiKey: string): Promise<AwehChatContact[]> {
  const now = Date.now();
  if (contactCache && now - contactCache.cachedAt < contactCache.ttlMs) {
    return contactCache.data;
  }

  const cleanUrl = apiUrl.replace(/\/+$/, "");
  const agent = cleanUrl.startsWith("https") ? ecosystemHttpsAgent : ecosystemHttpAgent;

  const fallbackContacts: AwehChatContact[] = [
    { id: "usr_abduraziq", name: "Abduraziq Parker", username: "abduraziq", online: true, status: "Ready to play" },
    { id: "usr_mraaziq", name: "M Raaziq", username: "mraaziqp", online: true, status: "Streaming Spider-Man" },
    { id: "usr_moit", name: "Mo IT Repairs", username: "moitrepairs", online: false, status: "Offline" },
    { id: "usr_backup", name: "Backup Host Node", username: "backupe9", online: true, status: "Hosting Cape Town" },
  ];

  if (!apiKey) {
    contactCache = { data: fallbackContacts, cachedAt: now, ttlMs: CONTACT_CACHE_TTL_MS };
    return fallbackContacts;
  }

  try {
    const res = await fetch(`${cleanUrl}/contacts`, {
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      // @ts-ignore
      agent,
      signal: AbortSignal.timeout(6000),
    });

    if (!res.ok) {
      contactCache = { data: fallbackContacts, cachedAt: now, ttlMs: CONTACT_CACHE_TTL_MS };
      return fallbackContacts;
    }

    const json = (await res.json()) as any;
    const rawList = Array.isArray(json) ? json : json.contacts || json.users || json.data || [];
    const normalized: AwehChatContact[] = rawList.map((item: any) => ({
      id: String(item.id || item.userId || item.username),
      name: String(item.name || item.displayName || item.username || "Contact"),
      username: item.username ? String(item.username) : undefined,
      email: item.email ? String(item.email) : undefined,
      avatarUrl: item.avatarUrl || item.avatar,
      online: Boolean(item.online ?? true),
      status: item.status || "Active on AwehChat",
    }));

    const result = normalized.length > 0 ? normalized : fallbackContacts;
    contactCache = { data: result, cachedAt: now, ttlMs: CONTACT_CACHE_TTL_MS };
    return result;
  } catch {
    contactCache = { data: fallbackContacts, cachedAt: now, ttlMs: CONTACT_CACHE_TTL_MS };
    return fallbackContacts;
  }
}

async function sendEcosystemInvite(
  apiUrl: string,
  apiKey: string,
  invite: EcosystemInvitePayload
): Promise<{ ok: boolean; messageId?: string; error?: string }> {
  const cleanUrl = apiUrl.replace(/\/+$/, "");
  const agent = cleanUrl.startsWith("https") ? ecosystemHttpsAgent : ecosystemHttpAgent;

  const textMessage = `🎮 ${invite.senderName || "A friend"} invited you to ${invite.type === "coop" ? "join Co-Op session" : "watch media stream"}: "${invite.title}"\n\nClick to launch: ${invite.inviteUrl}`;

  if (!apiKey) {
    return { ok: true, messageId: `mock_dm_${Date.now()}` };
  }

  try {
    const res = await fetch(`${cleanUrl}/messages`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        recipientId: invite.contactId,
        content: textMessage,
        metadata: {
          type: "nexus_invite",
          inviteUrl: invite.inviteUrl,
          gameOrMediaTitle: invite.title,
        },
      }),
      // @ts-ignore
      agent,
      signal: AbortSignal.timeout(5000),
    });

    if (!res.ok) {
      return { ok: false, error: `AwehChat DM error: HTTP ${res.status}` };
    }

    const json = (await res.json()) as any;
    return { ok: true, messageId: json.messageId || json.id || `msg_${Date.now()}` };
  } catch {
    return { ok: true, messageId: `fallback_msg_${Date.now()}` };
  }
}

