type LocalPersistState = {
  version: number;
  savedAt: string;
  mediaRoot?: string;
  vaultConfig: {
    root_path: string;
    bios_path: string;
    emulator_path: string;
    vault_id: string;
    brain_api_key: string;
    extra_scan_paths: string;
  };
  games: ReturnType<typeof rowToGame>[];
  setupEvents: { name: string; ok: boolean; detail: string; context: string; createdAt: string }[];
};

// NEXUS_DATA_DIR travels in .env with the drive, so it is frequently an absolute
// path for the OTHER operating system (a Linux "/media/<user>/..." root read on
// Windows, or a "X:\..." root read on Linux). Using it blindly sends all persisted
// state to a path that can never exist here. Only honour it when it is actually
// shaped for this platform; otherwise fall back to the per-OS default.
function isPathValidForThisPlatform(p: string): boolean {
  const v = p.trim();
  if (!v) return false;
  if (process.platform === "win32") {
    // Reject POSIX-absolute paths ("/media/..."), accept "X:\..." or UNC.
    return /^[a-zA-Z]:[\\/]/.test(v) || v.startsWith("\\\\");
  }
  // Reject Windows drive-letter paths on POSIX.
  return !/^[a-zA-Z]:[\\/]/.test(v);
}
const NEXUS_DATA_DIR_ENV = process.env.NEXUS_DATA_DIR?.trim() ?? "";
const PERSIST_DIR = (NEXUS_DATA_DIR_ENV && isPathValidForThisPlatform(NEXUS_DATA_DIR_ENV))
  ? NEXUS_DATA_DIR_ENV
  : path.join(process.env.APPDATA ?? path.join(os.homedir(), "AppData", "Roaming"), "NexusEmuHost");
const PERSIST_FILE = path.join(PERSIST_DIR, "host-state.json");
const LEGACY_PERSIST_DIR = path.join(process.env.APPDATA ?? path.join(os.homedir(), "AppData", "Roaming"), "NexusEmuHost");

const BOOTSTRAP_CACHE_TTL_MS = 10 * 60 * 1000;
type BootstrapPackCache = {
  key: string;
  buffer: Buffer;
  filename: string;
  generatedAt: number;
};
let bootstrapPackCache: BootstrapPackCache | null = null;

async function getMtimeMsSafe(filePath: string): Promise<number | null> {
  try {
    const info = await stat(filePath);
    return info.mtimeMs;
  } catch {
    return null;
  }
}

async function loadLocalPersistState(): Promise<LocalPersistState | null> {
  try {
    const raw = await readFile(PERSIST_FILE, "utf8");
    const parsed = JSON.parse(raw) as Partial<LocalPersistState>;
    if (!parsed || typeof parsed !== "object") return null;
    return {
      version: 1,
      savedAt: String(parsed.savedAt ?? ""),
      mediaRoot: String(parsed.mediaRoot ?? "").trim() || undefined,
      vaultConfig: {
        root_path: String(parsed.vaultConfig?.root_path ?? ""),
        bios_path: String(parsed.vaultConfig?.bios_path ?? ""),
        emulator_path: String(parsed.vaultConfig?.emulator_path ?? ""),
        vault_id: String(parsed.vaultConfig?.vault_id ?? "NV-9412-PRB"),
        brain_api_key: String((parsed.vaultConfig as any)?.brain_api_key ?? ""),
        extra_scan_paths: String((parsed.vaultConfig as any)?.extra_scan_paths ?? ""),
      },
      games: Array.isArray(parsed.games) ? parsed.games as ReturnType<typeof rowToGame>[] : [],
      setupEvents: Array.isArray(parsed.setupEvents)
        ? parsed.setupEvents
          .map((e: any) => ({
            name: String(e?.name ?? ""),
            ok: Boolean(e?.ok),
            detail: String(e?.detail ?? ""),
            context: String(e?.context ?? "setup"),
            createdAt: String(e?.createdAt ?? new Date().toISOString()),
          }))
          .slice(-200)
        : [],
    };
  } catch {
    return null;
  }
}

async function saveLocalPersistState(state: LocalPersistState): Promise<void> {
  await mkdir(PERSIST_DIR, { recursive: true });
  const tempPath = `${PERSIST_FILE}.tmp`;
  await writeFile(tempPath, JSON.stringify(state, null, 2), "utf8");
  await renameFile(tempPath, PERSIST_FILE);
}

// ─── CPU Load Sampling ──────────────────────────────────────────────────────
let cpuLoadCache = 0;
let gpuLoadCache = -1;
let lastCpuInfo = os.cpus().map((c) => ({ ...c.times }));

function startCpuSampling() {
  setInterval(() => {
    const current = os.cpus();
    const deltas = current.map((cpu, i) => {
      const prev = lastCpuInfo[i];
      const idle = cpu.times.idle - prev.idle;
      const total =
        Object.values(cpu.times).reduce((a, b) => a + b, 0) -
        Object.values(prev).reduce((a, b) => a + b, 0);
      return total === 0 ? 0 : (1 - idle / total) * 100;
    });
    cpuLoadCache = Math.round(
      deltas.reduce((a, b) => a + b, 0) / deltas.length
    );
    lastCpuInfo = current.map((c) => ({ ...c.times }));
  }, 2000);
}

let _gpuPollFailures = 0;
async function pollGpu() {
  try {
    const { stdout } = await execAsync(
      "nvidia-smi --query-gpu=utilization.gpu --format=csv,noheader,nounits"
    );
    gpuLoadCache = parseInt(stdout.trim(), 10);
    _gpuPollFailures = 0;
    setTimeout(pollGpu, 3000);
  } catch {
    gpuLoadCache = -1;
    _gpuPollFailures++;
    // Back off exponentially on repeated failures (no GPU / nvidia-smi not installed)
    // Max backoff: 10 minutes
    const delay = Math.min(600_000, 3000 * Math.pow(2, Math.min(_gpuPollFailures, 7)));
    setTimeout(pollGpu, delay);
  }
}

