// ─── Password Helpers (PBKDF2 — no extra packages) ─────────────────────────
function hashPassword(password: string): string {
  const salt = crypto.randomBytes(16).toString('hex');
  const hash = crypto.pbkdf2Sync(password, salt, 100_000, 64, 'sha512').toString('hex');
  return `${salt}:${hash}`;
}

function verifyPassword(password: string, stored: string): boolean {
  const [salt, hash] = stored.split(':');
  if (!salt || !hash) return false;
  try {
    const attempt = crypto.pbkdf2Sync(password, salt, 100_000, 64, 'sha512').toString('hex');
    return crypto.timingSafeEqual(Buffer.from(attempt, 'hex'), Buffer.from(hash, 'hex'));
  } catch { return false; }
}

function getAiResponseText(result: { text?: string | null }): string {
  const text = String(result.text ?? "").trim();
  if (!text) throw new Error("AI returned an empty response");
  return text.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, "").trim();
}

function parseAiJson<T = any>(rawText: string, fallback?: T): T {
  const cleaned = (rawText || "").trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, "").trim();
  try {
    return JSON.parse(cleaned) as T;
  } catch {
    const match = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
    if (match) {
      try {
        return JSON.parse(match[0]) as T;
      } catch {}
    }
    if (fallback !== undefined) return fallback;
    throw new Error(`Failed to parse AI JSON response`);
  }
}

function isTransientDbError(err: unknown): boolean {
  const code = String((err as { code?: unknown })?.code ?? "");
  const message = String((err as { message?: unknown })?.message ?? err ?? "");
  return ["ECONNRESET", "57P01", "57P02", "57P03", "53300"].includes(code)
    || /connection terminated unexpectedly|read econnreset|socket hang up|terminating connection/i.test(message);
}

// ─── Portable emulator lookup roots ───────────────────────────────────────────
// Emulators shipped alongside the app (vendor/) must be found FIRST so the whole
// stack travels with the drive and works on any machine it is plugged into.
// The per-emulator lists below were also missing the two locations Windows
// installers actually use — "%PROGRAMFILES%\<name>" and the winget package
// store — so an emulator could be installed and still report as "not found".
function emulatorCandidatePaths(dirNames: string[], exeNames: string[]): string[] {
  const out: string[] = [];
  const appRoot = process.cwd();
  const drives = ['I', 'C', 'D', 'E', 'F', 'G', 'H', 'J'];
  const roots: string[] = [
    // 1. Bundled with the app on the portable drive
    ...dirNames.map((d) => path.join(appRoot, "vendor", d)),
    ...dirNames.map((d) => path.join(appRoot, "vendor", d, `${d}-x64`)),
    ...dirNames.map((d) => path.join(appRoot, "emulators", d)),
    // 2. LaunchBox / Root drives
    ...drives.flatMap((drive) => dirNames.flatMap((d) => [
      path.join(`${drive}:\\`, d),
      path.join(`${drive}:\\`, `${d}-Win64`),
      path.join(`${drive}:\\LaunchBox\\Emulators`, d),
      path.join(`${drive}:\\LaunchBox\\ThirdParty`, d),
      path.join(`${drive}:\\Emulators`, d),
    ])),
    // 3. Standard Windows install locations
    ...dirNames.flatMap((d) => [
      path.join(process.env.PROGRAMFILES ?? "C:\\Program Files", d),
      path.join(process.env["PROGRAMFILES(X86)"] ?? "C:\\Program Files (x86)", d),
      path.join(process.env.LOCALAPPDATA ?? "", "Programs", d),
    ]),
  ];
  // 3. winget package store (flat layout, package dir name is unpredictable)
  const wingetPkgs = path.join(process.env.LOCALAPPDATA ?? "", "Microsoft", "WinGet", "Packages");
  const wingetLinks = path.join(process.env.LOCALAPPDATA ?? "", "Microsoft", "WinGet", "Links");
  for (const exe of exeNames) {
    for (const r of roots) out.push(path.join(r, exe));
    out.push(path.join(wingetLinks, exe));
    try {
      for (const entry of readdirSync(wingetPkgs)) {
        const base = path.join(wingetPkgs, entry);
        out.push(path.join(base, exe));
        // winget frequently nests one version folder deep
        try {
          for (const sub of readdirSync(base)) out.push(path.join(base, sub, exe));
        } catch { /* not a dir */ }
      }
    } catch { /* winget store absent */ }
  }
  return out;
}

