  // Auto-seed: create default "Moh's Circle" group and add all media_access users to it
  app.post("/api/host-groups/seed-default", async (req, res) => {
    if (!pool || !dbConnected) return res.status(503).json({ error: "DB not connected" });
    const auth = requireAnyAuth(req, res); if (!auth) return;
    if (!(await isAdminUser(auth))) return res.status(403).json({ error: "Admin only" });
    // Find or create the default group
    let g = await pool.query("SELECT * FROM host_groups WHERE owner_id=$1 AND name='Moh\\'s Circle' LIMIT 1", [auth.userId]).then(r => r.rows[0]).catch(() => null);
    if (!g) {
      g = await pool.query(
        `INSERT INTO host_groups (name,description,icon,color,owner_id,allow_media_access,allow_downloads)
         VALUES('Moh''s Circle','Default group — access to all host media','🎬','#4d7cff',$1,TRUE,TRUE) RETURNING *`,
        [auth.userId]
      ).then(r => r.rows[0]);
    }
    // Add all users with media_access to the group
    const users = await pool.query("SELECT id FROM users WHERE media_access=TRUE AND id!=$1", [auth.userId]);
    let added = 0;
    for (const u of users.rows) {
      await pool.query(
        `INSERT INTO host_group_members (group_id,user_id,added_by,can_download) VALUES($1,$2,$3,TRUE) ON CONFLICT DO NOTHING`,
        [g.id, u.id, auth.userId]
      ).catch(() => {});
      added++;
    }
    res.json({ ok: true, groupId: g.id, groupName: g.name, added });
  });

