  // Public host directory (only pro/unlimited hosts that marked is_public)
  app.get("/api/hosts/directory", async (req, res) => {
    if (!pool || !dbConnected) return res.status(503).json({ error: "DB not connected" });
    const q = String(req.query.q ?? '').trim();
    const plan = String(req.query.plan ?? '').trim();
    let sql = `SELECT hp.*, u.username, u.display_name,
               (SELECT COUNT(*)::int FROM host_access_requests har WHERE har.host_id=hp.id AND har.status='approved') as member_count
               FROM host_profiles hp
               JOIN users u ON u.id=hp.owner_id
               WHERE hp.is_public=TRUE AND hp.plan IN ('pro','unlimited')`;
    const params: unknown[] = [];
    if (q) { params.push(`%${q}%`); sql += ` AND (hp.name ILIKE $${params.length} OR hp.description ILIKE $${params.length})`; }
    if (plan && ['pro','unlimited'].includes(plan)) { params.push(plan); sql += ` AND hp.plan=$${params.length}`; }
    sql += ' ORDER BY member_count DESC, hp.created_at DESC LIMIT 50';
    const rows = await pool.query(sql, params).then(r => r.rows).catch(() => []);
    res.json(rows);
  });

