    const r = await pool.query(
      `UPDATE mega_hosts SET name=COALESCE($1,name), description=COALESCE($2,description),
       icon=COALESCE($3,icon), price_rands=COALESCE($4,price_rands), is_active=COALESCE($5,is_active)
       WHERE id=$6 AND owner_id=$7 RETURNING *`,
      [name ?? null, description ?? null, icon ?? null, price_rands ?? null, is_active ?? null, req.params.id, auth.userId]
    );
