    const auth = requireAnyAuth(req, res); if (!auth) return;
    const mh = await pool.query("SELECT * FROM mega_hosts WHERE id=$1 AND owner_id=$2", [req.params.id, auth.userId]).then(r => r.rows[0]).catch(() => null);
    if (!mh) return res.status(403).json({ error: "Only MegaHost owner can add contributors" });
