      const scanned = await refreshMediaLibrary(true);
      const videoCount = scanned.filter((m) => m.kind === "video").length;
      const rootsScanned = new Set([path.resolve(mediaRoot || DEFAULT_MEDIA_ROOT), ...MEDIA_DRIVE_ROOTS.map((r) => path.resolve(r))]).size;
      log("INFO", `PC video scan: ${videoCount} video(s) across ${rootsScanned} root(s)`, "media");
      res.setHeader("Cache-Control", "no-store");
